const pkg = await ctx.call("read", { path: "package.json" })
const root = await ctx.call("ls", { path: "." })
const verdict = await ctx.call("classify/triage/relevance", { task: "Read package.json and tell me the name field.", file: "package.json", excerpt: pkg.content })
console.log(pkg.content)
console.log(root.entries.map((e) => e.name).join(" "))
console.log(JSON.stringify(verdict.answers))
return ctx.continue()

